const db = require('./db');
exports.login = async (req, res) => {
  const rows = await db.query("SELECT * FROM users WHERE name='" + req.body.user + "' AND pw='" + req.body.pw + "'");
  if (rows.length) { res.cookie('session', req.body.user); res.send('ok'); } else res.status(401).send('Invalid password for ' + req.body.user);
};

